        var artifactRow=one(db.queryForList("SELECT * FROM artifact WHERE tenant_id=? AND artifact_id=? FOR UPDATE",tenant,artifact));var bindingRow=one(db.queryForList("SELECT * FROM artifact_content_binding WHERE tenant_id=? AND artifact_id=? FOR UPDATE",tenant,artifact));metadataEquals(row,artifactRow,manifest());metadataEquals(row,bindingRow,null);if(!str(row,"run_id").equals(str(artifactRow,"run_id"))||artifactRow.get("document_revision")!=null)bad();
